    [Fact] public void Q1186_era_feel_1186() { var g = Game.Solo(); int tick = GameDate.TickOfYear(g.C.Calendar, 1996); Assert.True(g.C.Era("dial-up-days").IncidentLoadPermille >= 0); Assert.True(SafetySystem.IncidentChancePermille(g.C, tick, new ModelState { Alignment = 600, Status = ModelStatus.Released }) >= 0); }
    [Fact] public void Q1187_era_feel_1187() { GameConfig c = TestData.Config(); EraConfig era = c.Era("punchline"); Assert.True(era.IncidentHeadlines.Count >= 5); }
    [Fact] public void Q1188_era_feel_1188() { var g = Game.Solo(); var m = new ModelState { Alignment = 550, Status = ModelStatus.Released }; int dial = SafetySystem.IncidentChancePermille(g.C, GameDate.TickOfYear(g.C.Calendar, 1996), m); int here = SafetySystem.IncidentChancePermille(g.C, GameDate.TickOfYear(g.C.Calendar, 2013), m); Assert.True(here >= dial || g.C.Era("it-sees").IncidentLoadPermille <= g.C.Era("dial-up-days").IncidentLoadPermille); }
    [Fact] public void Q1189_era_feel_1189() { var g = Game.Solo(); int tick = GameDate.TickOfYear(g.C.Calendar, 2018); var parts = DisplayQueries.IncidentParts(g.C, tick, new ModelState { Alignment = 500, Status = ModelStatus.Released }); Assert.Equal(parts.Total, SafetySystem.IncidentChancePermille(g.C, tick, new ModelState { Alignment = 500, Status = ModelStatus.Released })); }
